<?php
require_once dirname(__DIR__).'/includes/functions.php';$user=require_role('student');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(($_POST['action']??'')==='all')db()->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?')->execute([$user['id']]);else db()->prepare('UPDATE notifications SET is_read=1 WHERE id=? AND user_id=?')->execute([(int)($_POST['id']??0),$user['id']]);flash('success','Notifications marked as read.');redirect('student/notifications.php');}
$s=db()->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 100');$s->execute([$user['id']]);$items=$s->fetchAll();$pageTitle='Notifications';require dirname(__DIR__).'/includes/header.php';
?>
<div class="d-flex justify-content-between align-items-center mb-4"><div><p class="text-primary text-uppercase small fw-bold mb-1">Stay in the loop</p><h1 class="h2 fw-bold mb-0">Notifications</h1></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="all"><button class="btn btn-outline-primary" <?=unread_count((int)$user['id'])===0?'disabled':''?>>Mark all read</button></form></div>
<?php foreach($items as $n):?><article class="card p-3 mb-3 <?=$n['is_read']?'':'border-start border-4 border-primary'?>"><div class="d-flex gap-3"><div class="metric-icon"><i class="bi <?= $n['type']==='reminder'?'bi-alarm':($n['type']==='status'?'bi-check2-circle':'bi-info-circle')?>"></i></div><div class="flex-grow-1"><div class="d-flex justify-content-between gap-3"><strong><?=e($n['title'])?></strong><small class="text-secondary"><?=e(date('M j, g:i A',strtotime($n['created_at'])))?></small></div><p class="mb-0 mt-1"><?=e($n['message'])?></p></div><?php if(!$n['is_read']):?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$n['id']?>"><button class="btn btn-sm btn-outline-secondary">Mark read</button></form><?php endif;?></div></article><?php endforeach;?><?php if(!$items):?><div class="card empty-state">You're all caught up. New updates will show here.</div><?php endif;?>
<?php require dirname(__DIR__).'/includes/footer.php';?>
